<?php
 class Scheduler { const LOG = 'scheduler'; const MED_COMMON_SETTINGS_NAME = 'medCommon'; const UPDATE_DOCTOR_SETTINGS_PERMISSION = 'med-common-doctors-setting-publication'; const ERROR_UPDATE_DOCTOR_SETTINGS_PERMISSION = 'У Вас нет прав на редактирование данных настроек. Обратитесь к Администратору.'; public static function setup ($name, $action = null, $type = null, $periodicity = null) { $cmd = 'schtasks.exe'; $name = self::canonizeName($name); $exit = pclose(popen("$cmd /query /TN \"$name\"", 'r')); if ($exit != 0 && $exit != 1) { app_log($res = "Неизвестная ошибка при вызове $cmd для задания \"$name\", код ошибки $exit.", 2, self::LOG); return $res; } $isExists = $exit == 0; $isCreate = !empty($action); if (!$isCreate && !$isExists) { app_log("Задание \"$name\" изменений не требует.", 0, self::LOG); return true; } if ($isExists) { app_log("Удаление задания \"$name\"...", 0, self::LOG); pclose(popen("$cmd /end /TN \"$name\"", 'r')); $exit = pclose(popen("$cmd /delete /TN \"$name\" /F", 'r')); if ($exit != 0) { app_log($res = "Не удается удалить задание \"$name\", код ошибки $exit.", 2, self::LOG); return $res; } app_log("ОК", 3, self::LOG); } if ($isCreate) { app_log("Создание задания \"$name\", действие \"$action\" каждые $periodicity $type...", 0, self::LOG); $periodicity = $periodicity ?: 1; $temp = tempnam(false, false); $temp = self::setXml($temp, $action, $periodicity, $type); $exit = pclose(popen("$cmd /create /XML \"$temp\" /TN \"$name\" /RU \"SYSTEM\"", 'r')); unlink($temp); if ($exit != 0) { app_log($res = "Не удается создать задание \"$name\", код ошибки $exit.", 2, self::LOG); return $res; } app_log("ОК", 3, self::LOG); } return true; } private static function setXml($temp, $action,$periodicity, $type) { $xmlDir = __DIR__.'\sheduler.xml'; $xml = file_get_contents($xmlDir); list($command, $arguments) = safe_explode("-f", $action); $arguments = '-f '. trim($arguments); $phpDir = dirname(__DIR__,3); $phpDir = $phpDir.'\bin\php'; if ($type === 'minute') { $type = "M"; } elseif ($type === "hourly") { $type = "H"; } else { $type = ""; } $xml = mb_convert_encoding($xml, 'UTF-8', 'UTF-16'); $xml = str_replace("<Command></Command>","<Command>".trim($command)."</Command>",$xml); $xml = str_replace("<Arguments></Arguments>","<Arguments>".$arguments."</Arguments>",$xml); $xml = str_replace("<WorkingDirectory></WorkingDirectory>","<WorkingDirectory>".$phpDir."</WorkingDirectory>",$xml); $xml = str_replace("<Date></Date>", "<Date>".date("Y-m-d")."T".date("H:i:s")."</Date>", $xml); if ($type) { $xml = str_replace("<Interval></Interval>", "<Interval>" . "PT" . $periodicity . $type . "</Interval>", $xml); $xml = str_replace("<StartBoundary></StartBoundary>", "<StartBoundary>".date("Y-m-d")."T".date("H:i:s")."</StartBoundary>", $xml); } else { $xml = preg_replace('/<TimeTrigger>.*<\/TimeTrigger>/s', "<CalendarTrigger><StartBoundary>".date("Y-m-d")."T".date("H:i:s")."</StartBoundary><Enabled>true</Enabled><ScheduleByDay><DaysInterval>" .$periodicity . "</DaysInterval></ScheduleByDay></CalendarTrigger>", $xml); } file_put_contents($temp,$xml); return $temp; } public static function existsTask ($name) { $cmd = 'schtasks.exe'; $name = self::canonizeName($name); $exit = pclose(popen("$cmd /query /TN \"$name\"", 'r')); if ($exit != 0 && $exit != 1) { app_log($res = "Неизвестная ошибка при вызове $cmd для задания \"$name\", код ошибки $exit.", 2, self::LOG); return $res; } return $exit == 0; } public static function createConsolePhpAction ($script, $method, $config = null) { $php = getPhpBinPath() . 'php.cmd'; $script = realpath(__DIR__ . '/../' . $script); $config = $config ?: getSessionValue('config'); return "$php -f \"$script\" $config $method"; } public static function checkAccessUpdateDoctorSettings ($permission, $error) { if (!testUserAccess($permission)) { throw new Exception($error, ERROR_NOT_ALLOWED); } } public static function writeExtraSettings ($config, $name, $value, $scheduleSetup = true) { if ($name === self::MED_COMMON_SETTINGS_NAME) { self::checkAccessUpdateDoctorSettings(self::UPDATE_DOCTOR_SETTINGS_PERMISSION, self::ERROR_UPDATE_DOCTOR_SETTINGS_PERMISSION); } $data = empty($value) ? new stdClass() : $value; if ($scheduleSetup) { if (empty($data->scheduleUUID)) { $data->scheduleUUID = strtolower(str_replace('-', '', generateUUID())); } } $res = writeExtraSettings($config, $name, $data); $configStr = $config && is_string($config) ? $config : null; if ($res && $scheduleSetup) { $res = self::setup("$name ($data->scheduleUUID)", empty($data->scheduleActive) ? null : self::createConsolePhpAction($data->scheduleScript, $data->scheduleMethod, $configStr), isUndefinedProperty($data, 'scheduleType'), isUndefinedProperty($data, 'schedulePeriodicity') ); if ($res !== true) { throw new Exception($res, -1); } } return $res; } private static function canonizeName ($name) { if ($name[0] != '\\') { $name = "\\MAPSOFT\\MapWebServer\\$name"; } return $name; } }